COVERS = {'sprint1': 'mo.stop(project_tabs.value != \'Спринт 1\')\ndef _density(x, width=1000, height=90):\n    # Плотность спирта (ядерная оценка) — верхний край зелёной полосы под бокалом\n    x = np.asarray(x, dtype=float)\n    bw = 1.06 * x.std() * len(x) ** (-1 / 5)\n    grid = np.linspace(x.min(), x.max(), 160)\n    dens = np.exp(-0.5 * ((grid[:, None] - x[None, :]) / bw) ** 2).sum(axis=1)\n    dens = dens / dens.max()\n    pts = " ".join(f"{i / (len(grid) - 1) * width:.1f},{height - d * (height - 6):.1f}" for i, d in enumerate(dens))\n    return (f\'<svg class="hero-density" viewBox="0 0 {width} {height}" preserveAspectRatio="none" aria-hidden="true">\'\n            f\'<defs><linearGradient id="pour" x1="0" y1="0" x2="0" y2="1">\'\n            f\'<stop offset="0" stop-color="var(--data)" /><stop offset="1" class="pour-end" /></linearGradient></defs>\'\n            f\'<polygon fill="url(#pour)" points="0,{height} {pts} {width},{height}" /></svg>\'\n            f\'<div class="hero-density-cap">Край волны — плотность распределения спирта в {len(x)} винах, \'\n            f\'от {x.min():.1f} до {x.max():.1f} % об.</div>\')\n\nmo.Html(f"""\n<section class="hero hero-wine" id="top">\n  <div class="hero-intro">\n  <img class="wine-hero-art" src="./public/wine-glass.png" alt="" aria-hidden="true" fetchpriority="high" />\n  <div class="hero-kicker">Прикладная статистика · Lab01 — sprint 1</div>\n  <h1 class="hero-title">Три случайные величины <em>белого вина</em></h1>\n  <p class="hero-sub">pH, остаточный сахар и спирт в 4898 образцах Vinho Verde: почему они случайны,\n  как распределены, насколько независимы и что можно сказать о генеральной совокупности по выборке.</p>\n  </div>\n  <div class="hero-vars">\n    {_density(X["alc"])}\n    <a href="#rv1" class="hero-var"><span>01</span>pH<small>почти колокол, правый хвост</small></a>\n    <a href="#rv2" class="hero-var"><span>02</span>Остаточный сахар<small>длинный правый хвост</small></a>\n    <a href="#rv3" class="hero-var"><span>03</span>Спирт<small>плоский, с «зубцами»</small></a>\n  </div>\n  <p class="hero-sub" style="margin-top:18px">Генераторы случайных величин — на вкладке «Спринт 2», дополнительное исследование оценок мобильных интерфейсов (UICrit) — на вкладке «Доп. КТиД».</p>\n</section>\n""")', 'sprint2': '<section class="hero hero-s2" id="sprint2">\n      <div class="s2-intro">\n<img class="s2-bottle" src="./public/bottle_wine.png" alt="Бутылка белого вина с зелёной волной" fetchpriority="high" />\n<div class="hero-kicker">Прикладная статистика · Lab01 — sprint 2</div>\n      <h1 class="hero-title">Генераторы <em>случайных величин</em></h1>\n      <p class="hero-sub">Собственные генераторы pH, остаточного сахара и спирта белого вина: из равномерных чисел\n      вихря Мерсенна — в распределения, подобранные в первом спринте. Проверка против теории, против 4898 реальных\n      вин и 65 автотестов.</p>\n      </div>\n<div class="hero-vars">\n        <a href="#s2-ph" class="hero-var"><span>01</span>pH<small>лог-нормальное со сдвигом · полярный метод и метод отношений</small></a>\n        <a href="#s2-sugar" class="hero-var"><span>02</span>Остаточный сахар<small>эмпирическая CDF · метод Неймана для гаммы</small></a>\n        <a href="#s2-alc" class="hero-var"><span>03</span>Спирт<small>скошенное нормальное · Марсалья и Бокс — Мюллер</small></a>\n      </div>\n    </section>', 'uicrit': '<section class="hero browser-cover hero-study" id="extra">\n      <div class="browser-chrome" aria-hidden="true"><span class="browser-dots"><i></i><i></i><i></i></span>\n      <span class="browser-address">research / uicrit</span><span class="browser-symbol">↗</span></div>\n      <div class="hero-kicker">Прикладная статистика · Lab01 — Доп. КТиД</div>\n      <h1 class="hero-title">Красиво — значит удобно? <em>Оценки мобильных интерфейсов</em></h1>\n      <p class="hero-sub">UICrit: 1000 экранов Android-приложений, 2981 оценка аннотаторов и 11 430 замечаний\n      с рамками на экране. Проверяем, связаны ли эстетика и удобство, и смотрим, где на экране чаще всего находят проблемы.</p>\n      <div class="hero-vars">\n        <a href="#extra-eda" class="hero-var"><span>X · Y</span>Эстетика и удобство<small>средние оценки экрана, 1–10</small></a>\n        <a href="#extra-dependence" class="hero-var"><span>X ↔ Y</span>Зависимость<small>Пирсон, Спирмен, перестановки</small></a>\n        <a href="#extra-heatmap" class="hero-var"><span>▦</span>Тепловая карта<small>где на экране замечания</small></a>\n      </div>\n    </section>'}
